css:
.loader {
  position: relative;
  width: 34px;
  height: 52px;
  animation: vib 0.14s ease-in-out infinite;
}
.loader::before {
  content: "";
  position: absolute;
  bottom: 14px;
  left: 8px;
  width: 18px;
  height: 6px;
  background: #6366f1;
  border-radius: 3px;
}
.loader::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 6px;
  height: 16px;
  margin-left: -3px;
  border-radius: 0 0 3px 3px;
  background: #6366f1;
}
.loader i {
  position: absolute;
  bottom: 18px;
  width: 6px;
  height: 32px;
  border-radius: 3px 3px 0 0;
  background: #6366f1;
}
.loader i:nth-child(1) { left: 8px; }
.loader i:nth-child(2) { right: 8px; }
@keyframes vib {
  0%, 100% { transform: translateX(-1.5px); }
  50% { transform: translateX(1.5px); }
}
